const PANTRY_MHD_DAYS = [1, 2, 3, 5, 7, 14];
function normalizePantrySettings(raw) {
  const o = raw && typeof raw === 'object' ? raw : {};
  const d = parseInt(o.mhdDays, 10);
  return { mhdDays: PANTRY_MHD_DAYS.includes(d) ? d : 3 };
}
const AVATARS = {
  pet: [['🐶','Hund'],['🐱','Katze'],['🐰','Hase'],['🐹','Hamster'],['🐦','Vogel'],['🐠','Fisch']],
  male: [['👶🏼','Baby'],['👦🏼','Junge'],['👨🏼','Mann'],['👴🏼','Opa']],
  female: [['👶🏼','Baby'],['👧🏼','Mädchen'],['👩🏼','Frau'],['👵🏼','Oma']],
};

// Former example members (Anna/Jonas/Mia) - never shown as long as no profile is linked to
// them (the server removes them as well, see pb_hooks/pinn-benutzer.js).
const EXAMPLE_MEMBERS = { m1: ['Anna', 'Mama'], m2: ['Jonas', 'Papa'], m3: ['Mia', 'Kind'] };
function isExampleMember(m) {
  const ex = m && EXAMPLE_MEMBERS[String(m.id || '')];
  return !!ex && m.name === ex[0] && (m.role || '') === ex[1] && !m.photo && !m.avatar;
}

function defaultFamilyData() {
  return {
    members: [], // no example members: every profile is a member (created by the server along with it)
    mealPlan: [],
    recipes: [],
    recipeFavorites: [], // family favourites: { id: <recipe ID or 'pub:<ID>' for public recipes of others>, at }
    recipeTrash: [],     // deleted recipes, kept 7 days: { id: <recipe ID>, recipe, meals, favorite, deletedAt, by } (since 1.118.3)
    shoppingItems: [],
    shoppingHistory: [],
    shoppingLists: [],       // own shopping lists per store (the list "Essensplanung" is built in)
    shoppingTransferred: [], // { id: <mealPlan ID>, at } - meals whose ingredients were already moved to another list
    shoppingPlans: [],       // { id: <task ID>, listIds, createdAt, bookedAt } - planned shopping trips (task <-> shopping lists)
    shoppingListOrder: [],   // order of the shopping lists in the overview (via drag & drop)
    shoppingMealTarget: { listId: '', mode: 'mirror' }, // main store: where the ingredients of the meal plan go
    shoppingIngredientRules: [], // special lists: { id, preset, name, icon, listId, keywords, exclude, active }
    shoppingCategoryOrder: [],   // shopping lists: order of the categories (IDs, empty = default)
    pantryItems: [],         // pantry: { id, name, qty, unit, minQty, category, location, stores, note, updatedAt }
    pantryCategories: [],    // pantry: own categories (empty = default)
    pantryLocations: [],     // pantry: own storage locations (empty = default)
    pantrySettings: {},      // pantry: { mhdDays } - reminder before the best-before date (days in advance)
    pinboard: [],            // pin board: notes (see the „Pinnwand“ section and pb_hooks/pinn-pinnwand.js)
    familyLists: [],         // lists: packing lists, gifts, wish lists, checklists, ideas (see the „Listen“ section)
    listTemplates: [],       // lists: own templates
    documentCategories: [],  // documents: own categories (empty = default)
    emergencyPasses: {},     // family: emergency pass per member ID
    schoolProfiles: [],      // family → school & daycare: per child the institution, timetable, drop-off & pick-up
    schoolHomework: [],      // family → school & daycare: homework
    schoolLetters: [],       // family → school & daycare: parent letters with deadlines
    schoolClosures: [],      // family → school & daycare: closing days (shown in the calendar)
    pets: [],                // family → pets (see the „Haustiere“ section)
    petLog: [],              // family → pets: walks, feeding, medication (last 60 days)
    tasks: [],
    lastName: '',
    wohnform: 'familie',     // 'familie' or 'wg' (settings → family members → type of household)
    darkMode: false,
    themeColors: { paper: '#FFFBFB', pine: '#00374A', mustard: '#A67B01' },
    categoryActive: Object.fromEntries(CATEGORIES.map(c => [c, true])),
    recipeCategories: [...CATEGORIES], // stored, extendable copy - CATEGORIES stays only the initial suggestion
    appleCalendar: { selectedCalendars: [], calendarColors: {}, taskCalendarName: '', showTaskCalendarAsEvents: false },
    weatherLocation: { lat: null, lon: null, label: '' },
    rooms: [], // { id, name, color, icon, createdDate }
    roomSchedules: [], // { id, roomId, category, scheduleType: 'weekdays'|'interval', weekdays: ['mo',...], intervalDays, createdDate }
    trashBins: [], // { id, roomId, wasteType }
    smartDevices: [], // smart home: { id, name, icon, type, actions: [{ id, label, shortcut }] } (see the „Smarthome“ section)
    houseMaintenance: [], // home → maintenance plan (the server creates the tasks, see the „Haus“ section)
    cleaningCategories: [], // since 1.55.1 no fixed categories any more - every family creates its own
    kitchenTools: [
      { id: 'ofen', label: 'Backofen', active: true },
      { id: 'mixer', label: 'Mixer', active: true },
      { id: 'kuechenmaschine', label: 'Küchenmaschine', active: true },
      { id: 'thermomix', label: 'Thermomix', active: true },
      { id: 'airfryer', label: 'Heißluftfritteuse', active: true },
      { id: 'grill', label: 'Grill', active: true },
    ],
    favoriteTabs: [...DEFAULT_FAVORITE_TABS],
    guestHiddenViews: [],
    finance: defaultFinance(), // budget, categories, recurring expenses (the expenses themselves live in the "ausgaben" collection)
    doneTaskCleanupDays: 2, // 2 | 1 | 0 (immediately) - how long completed tasks stay visible
    defaultViewModeDesktop: 'timeline', // 'timeline' | 'list' - default view for events on iPad/desktop
    defaultViewScopeDesktop: 'both', // 'both' | 'uebersicht' | 'termine'
    defaultViewModeMobile: 'timeline', // the same two settings, separately for the phone
    defaultViewScopeMobile: 'both',
  };
}

// These variables are only filled with real data after loadFamilyData() (after login).
